CREATE TRIGGER `executions_policy_immutable` BEFORE UPDATE ON `executions` FOR EACH ROW BEGIN IF NOT (OLD.`execution_policy_version` <=> NEW.`execution_policy_version`) OR NOT (OLD.`resolved_retry_policy_json` <=> NEW.`resolved_retry_policy_json`) OR NOT (OLD.`resolved_fallback_policy_json` <=> NEW.`resolved_fallback_policy_json`) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Execution policy snapshot is immutable'; END IF; END;
